(()=>{
    const root=document.getElementById('tinct-onboarding-worlds-v5');
    const previewParams=new URLSearchParams(location.search);
    if(previewParams.get('hires')==='1')root.classList.add('is-hires');
    const coverData={"odyssey":"data:image/jpeg;base64,","meditations":"data:image/jpeg;base64,","frankenstein":"data:image/jpeg;base64,","pride":"data:image/jpeg;base64,","bible-old":"data:image/jpeg;base64,","pride-old":"data:image/jpeg;base64,","frankenstein-old":"data:image/jpeg;base64,"};
    const books={
      odyssey:{title:'The Odyssey',titleHtml:'The<br>Odyssey',author:'Homer',art:'odyssey',pages:'541 pages',readTime:'12 hours',listenTime:'14 hours',summary:'After ten years of war, Odysseus begins the long journey home to Ithaca—while his son searches for news and his household is overrun by rivals.',classicLabel:'Butler · 1900',classic:'“Tell me, O Muse, of that ingenious hero who travelled far and wide after he had sacked the famous town of Troy…”',modern:'“Tell me about the clever man who wandered far after the fall of Troy. He saw many cities and learned how their people thought…”',q1:'Who is Telemachus—and what has happened with him so far?',a1:'He is Odysseus’s son. Athena has pushed him to seek news of his father, and he is beginning to stand up to the suitors.',q2:'Get me up to speed on what I read last.',a2:'You left Ithaca with Telemachus preparing to sail. Athena is helping him secretly; the suitors still think he is powerless.'},
      meditations:{title:'Meditations',titleHtml:'Medi-<br>tations',author:'Marcus Aurelius',art:'meditations',pages:'304 pages',readTime:'7 hours',listenTime:'8 hours',summary:'Private reflections on attention, character, mortality and how to live steadily in a world you cannot control.',classicLabel:'George Long · 1862',classic:'“Begin the morning by saying to thyself, I shall meet with the busy-body, the ungrateful, arrogant, deceitful and envious…”',modern:'“When you wake up, remind yourself: today I will meet difficult people—ungrateful, arrogant, dishonest, jealous and unkind…”',q1:'What is the idea behind this passage?',a1:'Marcus is preparing himself not to be surprised by other people’s faults—and not to let them control his own character.',q2:'What have I read so far?',a2:'You have been tracing his argument that your judgments are yours to govern, even when events are not.'},
      bible:{title:'The Bible',titleHtml:'The<br>Bible',author:'Various',art:'bible-old',pages:'1,200 pages',readTime:'70 hours',listenTime:'75 hours',summary:'A library of history, poetry, wisdom, prophecy and letters that has shaped faith, language and culture for centuries.',classicLabel:'King James · 1611',classic:'“In the beginning God created the heaven and the earth.”',modern:'“In the beginning, God created the heavens and the earth.”',q1:'Where should I begin?',a1:'You can begin with Genesis for the opening story, Psalms for poetry, or one of the Gospels for the life of Jesus.',q2:'How should I approach this book?',a2:'Read it as a library rather than a single continuous volume, and let each book establish its own voice and purpose.'},
      frankenstein:{title:'Frankenstein',titleHtml:'Franken-<br>stein',author:'Mary Shelley',art:'frankenstein',pages:'280 pages',readTime:'6 hours',listenTime:'8 hours',summary:'A brilliant young scientist creates life—and discovers too late what ambition without responsibility can unleash.',classicLabel:'Mary Shelley · 1818',classic:'“It was on a dreary night of November that I beheld the accomplishment of my toils. With an anxiety almost amounting to agony…”',modern:'“It was a bleak November night when I finally saw my work succeed. I watched in agonized suspense as the creature began to stir…”',q1:'Why is Victor so obsessed with succeeding?',a1:'He wants to conquer the limits of life and death, but he has isolated himself so completely that ambition has replaced judgment.',q2:'Catch me up without spoilers.',a2:'Victor has pursued his experiment in secret. The closer he gets to success, the more his health and relationships collapse.'},
      pride:{title:'Pride & Prejudice',titleHtml:'Pride &<br>Prejudice',author:'Jane Austen',art:'pride',pages:'432 pages',readTime:'9 hours',listenTime:'11 hours',summary:'Elizabeth Bennet meets the proud Mr Darcy in a sharp, funny story about first impressions, family and love.',classicLabel:'Jane Austen · 1813',classic:'“It is a truth universally acknowledged, that a single man in possession of a good fortune, must be in want of a wife.”',modern:'“Everyone assumes that a wealthy single man must be looking for a wife—even before anyone knows what he actually wants.”',q1:'Why does Elizabeth dislike Darcy?',a1:'His pride wounded her immediately, and everything she has heard since has confirmed the first story she formed about him.',q2:'Catch me up on the relationships.',a2:'Jane and Bingley are drawn together. Elizabeth and Darcy are locked in mutual misreading, sharpened by Wickham’s story.'}
    };
    const prefaces={
      odyssey:{answer:'I want the adventure, but help me notice what the journey changes in Odysseus.',relevance:'The Odyssey is an adventure about getting home—but also about identity, temptation and what long absence does to a person. Its central question still feels modern: after everything changes you, can you return to the life you once knew?',characters:[{name:'Odysseus',role:'A king far from home',blurb:'Clever, proud and tested at every turn. The story asks whether he can become the man his home now needs.'},{name:'Penelope',role:'Queen of Ithaca',blurb:'Patient but never passive. She uses intelligence and restraint to protect a household under siege.'},{name:'Telemachus',role:'A son coming of age',blurb:'He begins unsure of himself and of his father. His search for news becomes a search for his own authority.'},{name:'Athena',role:'Goddess and guide',blurb:'A strategist who favors Odysseus and quietly shapes Telemachus. Her help always leaves room for human choice.'}]},
      meditations:{answer:'Help me turn the ideas into something practical without flattening the philosophy.',relevance:'Meditations remains powerful because it was never written as polished advice. It is a person under pressure reminding himself how to stay decent, attentive and free inside circumstances he cannot control.',characters:[{name:'Marcus',role:'Emperor and student',blurb:'The author writes to himself, not to an audience—testing how to live by his principles under pressure.'},{name:'Rusticus',role:'Teacher and influence',blurb:'The mentor Marcus credits with teaching him seriousness, discipline and the value of honest correction.'},{name:'Epictetus',role:'Stoic teacher',blurb:'His distinction between what is and is not under our control runs beneath many of Marcus’s reflections.'},{name:'Antoninus',role:'Adoptive father',blurb:'Marcus presents him as a model of steadiness, restraint and duty without performance.'}]},
      bible:{answer:'Help me understand the form and context of what I am reading without flattening its religious meaning.',relevance:'The Bible is a library of books written across centuries. Genre matters: story, law, poetry, wisdom, prophecy, Gospel and letter each ask to be read in a different way.',characters:[{name:'Adam',role:'First human',blurb:'The opening chapters use Adam to explore creation, responsibility and human limits.'},{name:'Eve',role:'First woman',blurb:'Eve stands at the beginning of the Bible’s account of human relationship, choice and consequence.'},{name:'Abraham',role:'Ancestor and wanderer',blurb:'His story centers on promise, trust, family and the long consequences of a call.'},{name:'Moses',role:'Prophet and leader',blurb:'He leads Israel from slavery and becomes the central mediator of law and covenant.'}]},
      frankenstein:{answer:'I want the gothic story, but help me track responsibility and loneliness as I read.',relevance:'Frankenstein still speaks directly to an age of powerful invention. Its deepest concern is not whether we can create something new, but whether ambition can outrun responsibility for what we bring into the world.',characters:[{name:'Victor',role:'Ambitious young scientist',blurb:'Brilliant and obsessive. His desire to conquer nature outruns his willingness to care for what he creates.'},{name:'The Creature',role:'Abandoned creation',blurb:'Sensitive, observant and rejected. The novel asks what turns suffering into rage—and who is responsible.'},{name:'Elizabeth',role:'Victor’s closest companion',blurb:'A source of affection and home whose perspective reveals the human cost of Victor’s secrecy.'},{name:'Walton',role:'Explorer and narrator',blurb:'His polar expedition frames the novel and mirrors Victor’s dangerous hunger for greatness.'}]},
      pride:{answer:'Help me enjoy the romance while noticing how first impressions distort what everyone sees.',relevance:'Pride and Prejudice endures because its romance is also a study of how intelligent people misread one another. Attraction, status and self-protection keep turning observation into a story that feels true.',characters:[{name:'Elizabeth',role:'Sharp-eyed heroine',blurb:'Quick, independent and perceptive—except where wit and wounded pride make a satisfying story too easy to believe.'},{name:'Darcy',role:'Reserved gentleman',blurb:'Proud, awkward and more capable of change than Elizabeth first imagines.'},{name:'Jane',role:'Elizabeth’s sister',blurb:'Warm and generous. Her instinct to see the best in others is both a strength and a vulnerability.'},{name:'Bingley',role:'Darcy’s friend',blurb:'Open-hearted and impressionable, especially when stronger personalities claim to know what is best for him.'}]}
    };
    const characterPortraits={
      odyssey:[
        'data:image/jpeg;base64,',
        'data:image/jpeg;base64,',
        'data:image/jpeg;base64,',
        'data:image/jpeg;base64,'
      ],
      meditations:[],bible:[],frankenstein:[],pride:[]
    };
    root.querySelectorAll('[data-cover]').forEach(image=>{image.src=coverData[image.dataset.cover]});
    const phone=root.querySelector('.tov5-phone');
    const note=root.querySelector('.tov5-note');
    const reduceMotion=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    let currentBook='odyssey';
    let currentFrame='library-demo';
    let autoFrames=previewParams.get('autoplay')!=='0';
    let demoTimer=0;
    let libraryScrollTimer=0;
    let libraryReturnTimer=0;
    let chatToken=0;
    const selectCharacter=index=>{
      const character=prefaces[currentBook].characters[index];
      root.querySelectorAll('[data-character]').forEach((button,buttonIndex)=>{
        const item=prefaces[currentBook].characters[buttonIndex];
        const portrait=characterPortraits[currentBook][buttonIndex]||'';
        button.setAttribute('aria-pressed',String(buttonIndex===index));
        button.querySelector('strong').textContent=item.name;
        button.querySelector('small').textContent=item.role;
        button.querySelector('[data-character-image]').src=portrait;
        button.querySelector('[data-character-image]').alt=portrait?item.name:'';
        button.querySelector('[data-character-image]').hidden=!portrait;
      });
      root.querySelector('[data-character-role]').textContent=character.role;
      root.querySelector('[data-character-name]').textContent=character.name;
      root.querySelector('[data-character-blurb]').textContent=character.blurb;
    };
    const animateChat=()=>{
      const token=++chatToken;
      const book=books[currentBook];
      const items=[...root.querySelectorAll('[data-chat-item]')];
      const copy=[book.q2,book.a2,book.q1,book.a1];
      const targets=[root.querySelector('[data-chat-q1]'),root.querySelector('[data-chat-a1]'),root.querySelector('[data-chat-q2]'),root.querySelector('[data-chat-a2]')];
      items.forEach((item,index)=>{item.classList.remove('is-shown');targets[index].textContent=copy[index]});
      if(reduceMotion){items.forEach(item=>item.classList.add('is-shown'));return}
      [150,580,1010,1440].forEach((delay,index)=>window.setTimeout(()=>{if(token===chatToken)items[index].classList.add('is-shown')},delay));
    };
    const showFrame=frame=>{
      if(libraryScrollTimer)window.clearTimeout(libraryScrollTimer);
      if(libraryReturnTimer)window.clearTimeout(libraryReturnTimer);
      currentFrame=frame;
      phone.dataset.frame=frame;
      phone.classList.toggle('is-demo-autoplay',autoFrames&&frame==='library-demo'&&!reduceMotion);
      root.querySelectorAll('[data-frame-panel]').forEach(panel=>panel.classList.toggle('is-current',panel.dataset.framePanel===frame));
      root.querySelectorAll('[data-frame-dot]').forEach(dot=>dot.setAttribute('aria-pressed',String(dot.dataset.frameDot===frame)));
      const book=books[currentBook];
      const stepCopy=frame==='library-demo'?['Preview · 1 of 3','Pick a book']:frame==='versions'?['Preview · 2 of 3','Pick your translation']:['Preview · 3 of 3','Talk with the book'];
      root.querySelector('[data-demo-step]').textContent=stepCopy[0];
      root.querySelector('[data-demo-step-title]').innerHTML=frame==='chat'?'<span class="tov5-talk-highlight">Talk</span> with the book':stepCopy[1];
      note.textContent=frame==='library-demo'?'Library · 90 classics and growing':book.title+' · '+(frame==='versions'?'translation, reading and listening':'conversation in four unhurried beats');
      if(frame==='library-demo'){
        const libraryScroll=root.querySelector('.tov5-demo-library-scroll');
        libraryScroll.scrollTop=0;
        if(!reduceMotion){
          libraryScrollTimer=window.setTimeout(()=>libraryScroll.scrollTo({top:105,behavior:'smooth'}),650);
          libraryReturnTimer=window.setTimeout(()=>libraryScroll.scrollTo({top:0,behavior:'smooth'}),2250);
        }
      }
      if(frame==='chat')animateChat();else chatToken++;
    };
    const stopAutoFrames=()=>{
      autoFrames=false;
      phone.classList.remove('is-demo-autoplay');
      if(demoTimer)window.clearTimeout(demoTimer);
      if(libraryScrollTimer)window.clearTimeout(libraryScrollTimer);
      if(libraryReturnTimer)window.clearTimeout(libraryReturnTimer);
    };
    const scheduleNextFrame=()=>{
      if(demoTimer)window.clearTimeout(demoTimer);
      if(!autoFrames||reduceMotion)return;
      demoTimer=window.setTimeout(()=>{
        if(!autoFrames)return;
        if(!root.querySelector('[data-view-panel="landing"]').classList.contains('is-current')){scheduleNextFrame();return}
        if(currentFrame==='library-demo'){
          if(currentBook!=='odyssey')setBook('odyssey');
          showFrame('versions');
          scheduleNextFrame();
        }else if(currentFrame==='versions'){
          showFrame('chat');
          autoFrames=false;
        }else{
          autoFrames=false;
        }
      },currentFrame==='library-demo'?5600:6500);
    };
    const setBook=key=>{
      currentBook=key;
      const book=books[key];
      phone.dataset.bookWorld=key;
      root.querySelectorAll('.tov5-zoom').forEach(zoom=>{zoom.dataset.bookWorld=key});
      root.querySelector('[data-world-art]').src=coverData[book.art];
      root.querySelector('[data-library-world-art]').src=coverData[book.art];
      root.querySelector('[data-your-library-world-art]').src=coverData[book.art];
      root.querySelector('[data-librarian-world-art]').src=coverData[book.art];
      root.querySelector('[data-book-detail-world-art]').src=coverData[book.art];
      root.querySelector('[data-edition-world-art]').src=coverData[book.art];
      root.querySelector('[data-preface-world-art]').src=coverData[book.art];
      root.querySelector('[data-current-cover]').src=coverData[book.art];
      root.querySelector('[data-current-cover]').alt=book.title;
      root.querySelector('[data-current-author]').textContent=book.author;
      root.querySelector('[data-current-title]').textContent=book.title;
      root.querySelector('[data-current-summary]').textContent=book.a2;
      root.querySelector('[data-book-detail-cover]').src=coverData[book.art];
      root.querySelector('[data-book-detail-cover]').alt=book.title;
      root.querySelector('[data-book-detail-author]').textContent=book.author;
      root.querySelector('[data-book-detail-title]').textContent=book.title;
      root.querySelector('[data-book-detail-summary]').textContent=book.summary;
      root.querySelector('[data-book-pages]').textContent=book.pages;
      root.querySelector('[data-book-read-time]').textContent=book.readTime;
      root.querySelector('[data-book-listen-time]').textContent=book.listenTime;
      root.querySelector('[data-preface-title]').textContent=book.title;
      root.querySelector('[data-preface-answer]').value='';
      root.querySelector('[data-preface-relevance]').textContent=prefaces[key].relevance;
      root.querySelector('[data-preface-thread]').hidden=true;
      root.querySelector('[data-standard-preface]').hidden=false;
      selectCharacter(0);
      root.querySelector('.tov5-edition-head img').src=coverData[book.art];
      root.querySelector('.tov5-edition-head small').textContent=book.title;
      root.querySelector('[data-edition-classic-name]').textContent=book.classicLabel;
      root.querySelector('[data-edition-classic-copy]').textContent=book.classic;
      root.querySelector('[data-edition-modern-copy]').textContent=book.modern;
      root.querySelector('[data-edition-short-classic]').textContent=book.classicLabel.split(' · ')[0].split(' ').at(-1);
      root.querySelector('[data-classic-label]').textContent=book.classicLabel;
      root.querySelector('[data-classic-copy]').textContent=book.classic;
      root.querySelector('[data-modern-copy]').textContent=book.modern;
      root.querySelectorAll('[data-book]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.book===key)));
      showFrame(currentFrame);
    };
    const showView=view=>{
      root.querySelectorAll('[data-view-panel]').forEach(panel=>panel.classList.toggle('is-current',panel.dataset.viewPanel===view));
      root.querySelectorAll('[data-view]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.view===view)));
      if(view==='library')replayShelf();
      if(view==='edition')note.textContent='Edition picker · select a card or open either translation menu';
      if(view==='preface')note.textContent='Mobile preface · one tap for standard, or talk and chat to tailor it';
    };
    const replayShelf=()=>{
      const track=root.querySelector('.tov5-library-track');
      track.classList.remove('is-nudging');
      void track.offsetWidth;
      if(!window.matchMedia('(prefers-reduced-motion: reduce)').matches)track.classList.add('is-nudging');
      note.textContent='Library reveal · a slower browse from later books back to the opening choices';
    };
    root.querySelectorAll('[data-book]').forEach(button=>button.addEventListener('click',()=>{setBook(button.dataset.book);showView('landing')}));
    root.querySelectorAll('[data-view]').forEach(button=>button.addEventListener('click',()=>showView(button.dataset.view)));
    root.querySelectorAll('[data-librarian-layout]').forEach(button=>button.addEventListener('click',()=>{
      root.querySelector('.tov5-librarian-zoom').dataset.librarianCurrent=button.dataset.librarianLayout;
      root.querySelectorAll('[data-librarian-layout]').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));
      showView('librarian');
    }));
    root.querySelectorAll('[data-open-librarian]').forEach(button=>button.addEventListener('click',()=>{
      const mode=button.dataset.openLibrarian;
      root.querySelector('.tov5-librarian-zoom').dataset.librarianCurrent=mode;
      root.querySelectorAll('[data-librarian-layout]').forEach(item=>item.setAttribute('aria-pressed',String(item.dataset.librarianLayout===mode)));
      showView('librarian');
    }));
    root.querySelectorAll('[data-librarian-enter]').forEach(button=>button.addEventListener('click',()=>{
      const mode=button.dataset.librarianEnter;
      root.querySelector('.tov5-librarian-zoom').dataset.librarianCurrent=mode;
      root.querySelectorAll('[data-librarian-layout]').forEach(item=>item.setAttribute('aria-pressed',String(item.dataset.librarianLayout===mode)));
      note.textContent=mode==='voice'?'Librarian · voice conversation':'Librarian · chat conversation';
    }));
    root.querySelectorAll('.tov5-librarian-close').forEach(button=>button.addEventListener('click',()=>showView('library')));
    root.querySelector('.tov5-end-voice').addEventListener('click',()=>showView('library'));
    root.querySelector('.tov5-voice-controls button[aria-label="Mute microphone"]').addEventListener('click',event=>{
      const button=event.currentTarget;
      const muted=button.getAttribute('aria-pressed')==='true';
      button.setAttribute('aria-pressed',String(!muted));
      button.setAttribute('aria-label',muted?'Mute microphone':'Unmute microphone');
      button.innerHTML=muted?'<i data-lucide="mic-off" aria-hidden="true"></i>':'<i data-lucide="mic" aria-hidden="true"></i>';
      note.textContent=muted?'Librarian · microphone live':'Librarian · microphone muted';
      if(window.lucide)window.lucide.createIcons();
    });
    const bookKeyFromButton=button=>{
      const cover=(button.querySelector('[data-cover]')?.dataset.cover||'').replace(/-old$/,'');
      if(books[cover])return cover;
      const copy=(button.textContent||'').toLowerCase();
      if(copy.includes('meditations'))return 'meditations';
      if(copy.includes('bible'))return 'bible';
      if(copy.includes('frankenstein'))return 'frankenstein';
      if(copy.includes('pride'))return 'pride';
      return 'odyssey';
    };
    const libraryBookSelector='.tov5-library-track > button, .tov5-library-section > div > button, .tov5-librarian-chat-books > button, .tov5-librarian-voice-books > button, [data-open-book]';
    root.querySelectorAll(libraryBookSelector).forEach(button=>button.addEventListener('click',()=>{
      setBook(bookKeyFromButton(button));
      showView('book-detail');
    }));
    root.querySelector('.tov5-library-search input').addEventListener('input',event=>{
      const query=event.currentTarget.value.trim().toLowerCase();
      root.querySelectorAll('.tov5-library-track > button, .tov5-library-section > div > button').forEach(button=>{
        button.hidden=Boolean(query)&&!(button.textContent||'').toLowerCase().includes(query);
      });
    });
    root.querySelectorAll('[data-character]').forEach(button=>button.addEventListener('click',()=>selectCharacter(Number(button.dataset.character))));
    root.querySelectorAll('[data-preface-mode]').forEach(button=>button.addEventListener('click',()=>{
      root.querySelectorAll('[data-preface-mode]').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));
      const answerButton=root.querySelector('.tov5-preface-composer button');
      const answerCopy=root.querySelector('[data-preface-answer]');
      answerButton.setAttribute('aria-label',button.dataset.prefaceMode==='talk'?'Speak your request':'Send your request');
      answerButton.innerHTML=button.dataset.prefaceMode==='talk'?'<i data-lucide="mic" aria-hidden="true"></i>':'<i data-lucide="send" aria-hidden="true"></i>';
      answerCopy.textContent=button.dataset.prefaceMode==='talk'?'What would you like to understand or notice?':'Ask for context or tell me what interests you…';
      if(window.lucide)window.lucide.createIcons();
    }));
    root.querySelector('[data-standard-preface]').addEventListener('click',event=>{
      event.currentTarget.hidden=true;
      root.querySelector('[data-preface-thread]').hidden=false;
      note.textContent='The book answered with a spoiler-free overview';
    });
    root.querySelectorAll('[data-preface-prompt]').forEach(button=>button.addEventListener('click',()=>{
      root.querySelector('[data-preface-answer]').value=button.dataset.prefacePrompt;
      root.querySelector('[data-preface-answer]').focus();
    }));
    root.querySelector('.tov5-preface-talk').addEventListener('click',()=>{
      note.textContent='Opening the book’s voice conversation';
    });
    root.querySelector('.tov5-preface-dictate').addEventListener('click',()=>{
      root.querySelector('[data-preface-answer]').value='Give me a spoiler-free overview';
      note.textContent='Dictation added to the message field';
    });
    root.querySelector('.tov5-preface-send').addEventListener('click',()=>{
      const input=root.querySelector('[data-preface-answer]');
      if(!input.value.trim())return;
      root.querySelector('.tov5-preface-thread .tov5-q').textContent=input.value.trim();
      root.querySelector('[data-preface-thread]').hidden=false;
      root.querySelector('[data-standard-preface]').hidden=true;
      input.value='';
      note.textContent='Message sent to the book';
    });
    root.querySelectorAll('.tov5-angle-options button').forEach(button=>button.addEventListener('click',()=>root.querySelectorAll('.tov5-angle-options button').forEach(item=>item.setAttribute('aria-pressed',String(item===button)))));
    root.querySelectorAll('[data-begin-reading]').forEach(button=>button.addEventListener('click',()=>window.parent.location.assign('/lab/phone')));
    root.querySelectorAll('[data-frame-dot]').forEach(dot=>dot.addEventListener('click',()=>{stopAutoFrames();showFrame(dot.dataset.frameDot)}));
    root.querySelector('[data-pick-demo-book="odyssey"]').addEventListener('click',buttonEvent=>{
      stopAutoFrames();
      setBook('odyssey');
      buttonEvent.currentTarget.setAttribute('aria-pressed','true');
      window.setTimeout(()=>showFrame('versions'),260);
    });
    root.querySelector('.tov5-demo-library-scroll').addEventListener('pointerdown',()=>{if(libraryScrollTimer)window.clearTimeout(libraryScrollTimer)},{passive:true});
    root.querySelectorAll('[data-category]').forEach(button=>button.addEventListener('click',()=>{
      root.querySelectorAll('[data-category]').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));
      note.textContent='Library · '+button.dataset.category;
    }));
    root.querySelectorAll('[data-shelf-arrow]').forEach(button=>button.addEventListener('click',()=>{
      const viewport=root.querySelector('.tov5-library-viewport');
      root.querySelector('.tov5-library-track').classList.remove('is-nudging');
      viewport.scrollBy({left:button.dataset.shelfArrow==='right'?180:-180,behavior:'smooth'});
    }));
    root.querySelectorAll('[data-mini-arrow]').forEach(button=>button.addEventListener('click',()=>{
      root.querySelector('[data-mini-shelf]').scrollBy({left:button.dataset.miniArrow==='right'?150:-150,behavior:'smooth'});
    }));
    root.querySelectorAll('[data-reader-arrow]').forEach(button=>button.addEventListener('click',()=>{
      root.querySelector('[data-reader-carousel]').scrollBy({left:button.dataset.readerArrow==='right'?270:-270,behavior:'smooth'});
    }));
    root.querySelectorAll('[data-edition-choice]').forEach(button=>button.addEventListener('click',()=>{
      const choice=button.dataset.editionChoice;
      root.querySelectorAll('[data-edition-card]').forEach(card=>card.classList.toggle('is-selected',card.dataset.editionCard===choice));
      root.querySelectorAll('[data-edition-choice]').forEach(item=>item.setAttribute('aria-pressed',String(item.dataset.editionChoice===choice)));
      root.querySelector('.tov5-continue').textContent=choice==='both'?'Continue with Both':choice==='classic'?'Continue with Classic':'Continue with Modern';
    }));
    root.querySelectorAll('[data-edition-menu-button]').forEach(button=>button.addEventListener('click',()=>root.querySelectorAll('[data-edition-menu]').forEach(menu=>menu.classList.toggle('is-open',menu.dataset.editionMenu===button.dataset.editionMenuButton))));
    root.querySelectorAll('[data-close-menu]').forEach(button=>button.addEventListener('click',()=>root.querySelectorAll('[data-edition-menu]').forEach(menu=>menu.classList.remove('is-open'))));
    root.querySelector('.tov5-library-viewport').addEventListener('pointerdown',()=>root.querySelector('.tov5-library-track').classList.remove('is-nudging'),{once:true});
    phone.addEventListener('pointerdown',stopAutoFrames,{once:true});
    phone.addEventListener('focusin',stopAutoFrames,{once:true});
    const previewBook=previewParams.get('book');
    setBook(books[previewBook]?previewBook:'odyssey');
    const previewFrame=previewParams.get('frame');
    if(previewFrame==='library-demo'||previewFrame==='versions'||previewFrame==='chat'){
      autoFrames=false;
      showFrame(previewFrame);
    }
    const previewView=previewParams.get('view');
    if(previewView==='landing'||previewView==='library'||previewView==='your-library'||previewView==='librarian'||previewView==='book-detail'||previewView==='edition'||previewView==='preface')showView(previewView);
    const previewLibrarian=previewParams.get('librarian');
    if(['choice','focus','voice'].includes(previewLibrarian)){
      root.querySelector('.tov5-librarian-zoom').dataset.librarianCurrent=previewLibrarian;
      root.querySelectorAll('[data-librarian-layout]').forEach(item=>item.setAttribute('aria-pressed',String(item.dataset.librarianLayout===previewLibrarian)));
      showView('librarian');
    }
    const previewMenu=previewParams.get('menu');
    if(previewMenu==='human'||previewMenu==='ai')root.querySelector(`[data-edition-menu="${previewMenu}"]`).classList.add('is-open');
    scheduleNextFrame();
  })();

(() => {
    const params = new URLSearchParams(window.location.search);
    if (params.get('embed') !== '1') return;

    const landing = document.querySelector('[data-view-panel="landing"]');
    landing?.querySelector('.tov5-brand button')?.addEventListener('click', () => window.parent.location.assign('/lab/library'));
    landing?.querySelector('.tov5-footer button')?.addEventListener('click', () => {
      window.parent.history.pushState({}, '', '/lab/library');
      document.querySelectorAll('[data-view-panel]').forEach(panel => panel.classList.toggle('is-current', panel.dataset.viewPanel === 'library'));
    });

    const chat=document.querySelector('.tov5-librarian-focus');
    const chatInput=chat?.querySelector('input[aria-label="Message the librarian"]');
    const chatSend=chat?.querySelector('button[aria-label="Send"]');
    const submitChat=async()=>{
      const question=chatInput?.value.trim();
      if(!question)return;
      chatInput.value='';
      const thread=chat.querySelector('.tov5-librarian-chat');
      const user=document.createElement('p');
      user.textContent=question;
      thread.appendChild(user);
      const answer=document.createElement('p');
      answer.textContent='Reading your question…';
      thread.appendChild(answer);
      try{
        const response=await fetch('/api/lab-chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({model:'claude-sonnet-4-6',max_tokens:500,stream:false,system:"You are Tinct's librarian. Recommend public-domain classics warmly and concisely. Ask at most one useful follow-up question. Never invent availability.",messages:[{role:'user',content:question}]})});
        const data=await response.json();
        answer.textContent=data?.content?.[0]?.text||'The librarian is unavailable just now.';
      }catch{
        answer.textContent='The librarian is unavailable just now.';
      }
      thread.scrollTop=thread.scrollHeight;
    };
    chatSend?.addEventListener('click',submitChat);
    chatInput?.addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();submitChat();}});

    document.querySelectorAll('[data-librarian-enter="voice"], [data-open-librarian="voice"]').forEach(button=>button.addEventListener('click',()=>{
      const voice=document.querySelector('.tov5-librarian-voice');
      voice?.setAttribute('data-voice-adapter','useLabAsk/useVoiceSession');
      const status=voice?.querySelector(':scope > small');
      const heading=voice?.querySelector(':scope > h2');
      const copy=voice?.querySelector(':scope > p');
      if(status)status.textContent='Ready to talk';
      if(heading)heading.textContent='Start a voice conversation';
      if(copy)copy.textContent='Voice uses the existing Tinct session controls when connected.';
      window.parent.postMessage({type:'tinct:library-voice-start'},window.location.origin);
    }),true);
  })();
